<div class="page-heading"><div><span class="eyebrow">Admin · Booking details</span><h1>All bookings</h1><p>Follow every request from pending through its final vaccination outcome.</p></div></div>
<form class="filter-bar" method="get" action="index.php"><input type="hidden" name="route" value="admin.bookings"><label>Status<select name="status" onchange="this.form.submit()"><?php foreach (['all','pending','approved','rejected','completed','not_vaccinated'] as $option): ?><option value="<?= e($option) ?>" <?= $status === $option ? 'selected' : '' ?>><?= e(status_label($option)) ?></option><?php endforeach; ?></select></label></form>
<section class="panel table-panel"><?php if (!$bookings): ?><div class="empty-inline"><p>No bookings match this status.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Date &amp; status</th><th>Child / parent</th><th>Vaccine</th><th>Hospital</th><th>Notes</th></tr></thead><tbody><?php foreach ($bookings as $booking): ?><tr><td><strong><?= e(display_date($booking['appointment_date'])) ?></strong><small><?= e(display_date($booking['appointment_time'], 'g:i A')) ?></small><span class="status status-<?= e($booking['status']) ?>"><?= e(status_label($booking['status'])) ?></span></td><td><?= e($booking['child_name']) ?><small>Parent: <?= e($booking['parent_name']) ?></small></td><td><?= e($booking['vaccine_name']) ?><small><?= e($booking['dose_label']) ?></small></td><td><?= e($booking['hospital_name']) ?></td><td><?= e($booking['hospital_notes'] ?: $booking['admin_notes'] ?: $booking['reason'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
